params.command:
$ErrorActionPreference='Stop'
$repo='C:\Users\Xxkan\local-ai-workspaces\mhw-mods'
$wt='C:\Users\Xxkan\agent-worktrees\verify-updater-release-gate-governance'
$expected='6f54623190e3af6dd0e111778ec60e38db1ee48a'
git -C $repo fetch origin --prune
$actual=(git -C $repo rev-parse origin/fix/updater-release-gate-governance-20260929).Trim()
if($actual -ne $expected){throw "Branch head mismatch expected=$expected actual=$actual"}
if(Test-Path $wt){ git -C $repo worktree remove --force $wt 2>$null; Remove-Item -Recurse -Force $wt -ErrorAction SilentlyContinue }
git -C $repo worktree add --detach $wt $expected
try {
  powershell.exe -NoProfile -ExecutionPolicy Bypass -File "$wt\scripts\Test-AgentHandoff.ps1" -Root $wt
  if($LASTEXITCODE -ne 0){throw 'Test-AgentHandoff failed'}
  powershell.exe -NoProfile -ExecutionPolicy Bypass -File "$wt\scripts\Verify-Release.ps1"
  if($LASTEXITCODE -ne 0){throw 'Verify-Release failed'}
  Write-Output "VERIFIED_SHA=$expected"
  Write-Output 'TEST_AGENT_HANDOFF=PASS'
  Write-Output 'VERIFY_RELEASE=PASS'
} finally { git -C $repo worktree remove --force $wt 2>$null }
